    public class CabinDemoTests
    {
        private Scene scene,previous;private SyntheticInputScope inputs;private bool background;
        [Test]public void P09_A01_SavedDemoHasOnePlayerEchoCameraAndOwnBakedDataReferences()
        {
            var preview=EditorSceneManager.OpenPreviewScene(CabinDemoSetup.ScenePath);
            try{var roots=preview.GetRootGameObjects();var demo=roots.SelectMany(r=>r.GetComponentsInChildren<CabinDemo>()).Single();var camera=demo.GetComponentInChildren<Camera>();Assert.That(roots.SelectMany(r=>r.GetComponentsInChildren<Camera>()).Count(c=>c.enabled&&c.gameObject.activeInHierarchy),Is.EqualTo(1));Assert.That(demo.Echo,Is.Not.Null);Assert.That(textNav(),Does.Contain(AssetDatabase.AssetPathToGUID(CabinDemoSetup.DataFolder+"/NavMesh.asset")));Assert.That(camera.GetComponent<ScanWaveView>().Source,Is.SameAs(demo.Echo.GetComponent<ScanWaveEmitter>()));Assert.That(roots.SelectMany(r=>r.GetComponentsInChildren<DistanceShadowCaster>()).Single().TargetCamera,Is.SameAs(camera));Assert.That(demo.GetComponent<NavMeshObstacle>().carving,Is.True);Assert.That(GraphicsSettings.currentRenderPipeline.name,Is.EqualTo("ES_Gameplay_ForwardHDR"));var text=System.IO.File.ReadAllText(CabinDemoSetup.ScenePath);foreach(var file in new[]{"LightingData.asset","OcclusionCullingData.asset"})Assert.That(text,Does.Contain(AssetDatabase.AssetPathToGUID(CabinDemoSetup.DataFolder+"/"+file)));}
            finally{EditorSceneManager.ClosePreviewScene(preview);}
        }
        private static string textNav()=>System.IO.File.ReadAllText(CabinDemoSetup.ScenePath);
        private IEnumerator Key(Key key){InputSystem.QueueStateEvent(inputs.Keyboard,new KeyboardState(key));yield return R04ShadowProbe.Frame();InputSystem.QueueStateEvent(inputs.Keyboard,new KeyboardState());yield return R04ShadowProbe.Frame();}
        [UnityTest]public IEnumerator P09_A02_ActualBootstrapNativeCommandsAndModalJournalBoundaries()
        {
            yield return new EnterPlayMode();background=Application.runInBackground;Application.runInBackground=true;previous=SceneManager.GetActiveScene();inputs=new SyntheticInputScope();scene=EditorSceneManager.LoadSceneInPlayMode(CabinDemoSetup.ScenePath,new LoadSceneParameters(LoadSceneMode.Additive,LocalPhysicsMode.Physics3D));var timer=System.Diagnostics.Stopwatch.StartNew();while(!scene.isLoaded){if(timer.Elapsed.TotalSeconds>5)Assert.Fail("Demo load timeout.");yield return null;}SceneManager.SetActiveScene(scene);var demo=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<CabinDemo>()).Single();while(!demo.Ready){if(timer.Elapsed.TotalSeconds>5)Assert.Fail("Demo initialization timeout.");yield return R04ShadowProbe.Frame();}demo.GetComponentInChildren<Camera>().enabled=false;var reader=demo.GetComponent<PlayerInputReader>();reader.SetApplicationFocus(true);reader.SetPointerCaptured(true);demo.Echo.AutomaticWarningsEnabled=false;var controls=demo.GetComponent<CabinControls>();Assert.That(demo.Echo.CurrentMode,Is.EqualTo(IntentKind.Follow));Assert.That(GameRuntimeOptions.UseLLM,Is.False);yield return Key(UnityEngine.InputSystem.Key.Tab);Assert.That(controls.IsOpen,Is.True);Assert.That(reader.UiBlocked,Is.True);yield return Key(UnityEngine.InputSystem.Key.J);Assert.That(demo.GetComponent<JournalPanel>().IsOpen,Is.False);controls.TargetButton("terminal_data_01").onClick.Invoke();Assert.That(controls.SelectedTarget,Is.EqualTo("terminal_data_01"));controls.CommandButton(IntentKind.Wait).onClick.Invoke();Assert.That(controls.IsOpen,Is.False);Assert.That(demo.Echo.CurrentMode,Is.EqualTo(IntentKind.Wait));reader.SetPointerCaptured(true);yield return Key(UnityEngine.InputSystem.Key.Digit1);Assert.That(demo.Echo.CurrentMode,Is.EqualTo(IntentKind.Follow));yield return Key(UnityEngine.InputSystem.Key.Digit3);Assert.That(demo.Echo.CurrentMode,Is.EqualTo(IntentKind.Investigate));yield return Key(UnityEngine.InputSystem.Key.Digit2);Assert.That(demo.Echo.CurrentMode,Is.EqualTo(IntentKind.Wait));WorldTarget.Active.TryGet("power_panel_01",out var panel);var panelPose=panel.transform.position;Assert.That(demo.Echo.GetComponent<EchoNavigation>().TryBind(new Vector3(3.8f,0,-1.5f)),Is.True);var direction=panel.transform.position-demo.Echo.transform.position;direction.y=0;demo.Echo.transform.rotation=Quaternion.LookRotation(direction);scene.GetPhysicsScene().Simulate(.02f);Assert.That(controls.Submit(IntentKind.Warn),Is.True);Assert.That(demo.Echo.CurrentMode,Is.EqualTo(IntentKind.Warn));Assert.That(panel.transform.position,Is.EqualTo(panelPose));Assert.That(controls.SelectTarget("not_in_scene"),Is.False);Assert.That(controls.Submit(IntentKind.Answer),Is.False);yield return Key(UnityEngine.InputSystem.Key.J);Assert.That(demo.GetComponent<JournalPanel>().IsOpen,Is.True);Assert.That(controls.SetOpen(true),Is.False);yield return Key(UnityEngine.InputSystem.Key.Escape);Assert.That(demo.GetComponent<JournalPanel>().IsOpen,Is.False);
        }
        [Serializable]private class DoorwayResult{public bool blockedComplete,asideComplete,discovered;public string blockedStatus,asideStatus,mode,navFailure,scanFailure,speech;public Vector3 position,approvedPoint;}
        [UnityTest]public IEnumerator P09_A03_ActualPlayerObstaclePathAndInvestigationAfterStandingAside()
        {
            yield return new EnterPlayMode();background=Application.runInBackground;Application.runInBackground=true;previous=SceneManager.GetActiveScene();scene=EditorSceneManager.LoadSceneInPlayMode(CabinDemoSetup.ScenePath,new LoadSceneParameters(LoadSceneMode.Additive,LocalPhysicsMode.Physics3D));var timer=System.Diagnostics.Stopwatch.StartNew();while(!scene.isLoaded){if(timer.Elapsed.TotalSeconds>5)Assert.Fail("Demo load timeout.");yield return null;}SceneManager.SetActiveScene(scene);var demo=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<CabinDemo>()).Single();while(!demo.Ready){if(timer.Elapsed.TotalSeconds>5)Assert.Fail("Bootstrap timeout.");yield return R04ShadowProbe.Frame();}demo.GetComponent<FirstPersonMotor>().enabled=false;demo.GetComponentInChildren<Camera>().enabled=false;demo.Echo.AutomaticWarningsEnabled=false;Assert.That(demo.Echo.TrySubmit(ScriptCommands.Wait(),out _),Is.True);var nav=demo.Echo.GetComponent<EchoNavigation>();Assert.That(nav.TryBind(new Vector3(1.5f,0,-2)),Is.True);WorldTarget.Active.TryGet("scan_mark_01",out var mark);var result=new DoorwayResult{approvedPoint=mark.GetComponent<EchoTargetPermissions>().ApproachPoint.position};var controller=demo.GetComponent<CharacterController>();controller.enabled=false;demo.transform.position=new Vector3(6.5f,.05f,1);controller.enabled=true;scene.GetPhysicsScene().Simulate(.02f);yield return new WaitForSecondsRealtime(.5f);var filter=new NavMeshQueryFilter{agentTypeID=nav.Agent.agentTypeID,areaMask=nav.Agent.areaMask};var path=new NavMeshPath();result.blockedComplete=NavMesh.CalculatePath(nav.Position,result.approvedPoint,filter,path)&&path.status==NavMeshPathStatus.PathComplete;result.blockedStatus=path.status.ToString();controller.enabled=false;demo.transform.position=new Vector3(7.7f,.05f,1);controller.enabled=true;scene.GetPhysicsScene().Simulate(.02f);yield return new WaitForSecondsRealtime(.5f);result.asideComplete=NavMesh.CalculatePath(nav.Position,result.approvedPoint,filter,path)&&path.status==NavMeshPathStatus.PathComplete;result.asideStatus=path.status.ToString();Assert.That(demo.Echo.TrySubmit(ScriptCommands.Investigate(mark.Id),out _),Is.True);var scanner=demo.Echo.GetComponent<EchoScanController>().Scanner;timer.Restart();while(!scanner.Ledger.HasDiscovered(mark.Id)&&timer.Elapsed.TotalSeconds<18){scene.GetPhysicsScene().Simulate(.02f);yield return R04ShadowProbe.Frame();}result.discovered=scanner.Ledger.HasDiscovered(mark.Id);result.position=nav.Position;result.mode=demo.Echo.CurrentMode.ToString();result.navFailure=nav.Failure.ToString();result.scanFailure=scanner.Failure.ToString();result.speech=demo.Echo.LastSpeech;System.IO.File.WriteAllText("Docs/Tests/Stage1/Evidence/S1-P09/PlayerDoorwayNavigation.json",JsonUtility.ToJson(result,true));Assert.That(result.asideComplete&&result.discovered,Is.True,JsonUtility.ToJson(result,true));
        }
        [UnityTearDown]public IEnumerator After(){if(inputs!=null){inputs.Dispose();Assert.That(inputs.IsRestored,Is.True);inputs=null;}if(Application.isPlaying){if(previous.IsValid())SceneManager.SetActiveScene(previous);var operation=scene.IsValid()?SceneManager.UnloadSceneAsync(scene):null;var timer=System.Diagnostics.Stopwatch.StartNew();while(operation!=null&&!operation.isDone){if(timer.Elapsed.TotalSeconds>5)throw new TimeoutException("Demo unload timeout.");yield return null;}Application.runInBackground=background;yield return new ExitPlayMode();}}
    }
}
